@Service
class OrderService {
    private final ApplicationEventPublisher publisher;

    OrderService(ApplicationEventPublisher publisher) {
        this.publisher = publisher; // wstrzykiwany jak KAZDY inny bean
    }

    void placeOrder(String orderId) {
        // logika skladania zamowienia...
        publisher.publishEvent(new OrderPlacedEvent(this, orderId));
    }
}

@Component
class EmailNotificationListener implements ApplicationListener<OrderPlacedEvent> {
    public void onApplicationEvent(OrderPlacedEvent event) {
        System.out.println("Wysylam email dla zamowienia: " + event.getOrderId());
    }
}
// OrderService NIE WIE NIC o EmailNotificationListener - zaden import, zadna zaleznosc

record OrderPlacedEvent(String orderId) {} // ZWYKLY rekord, BEZ dziedziczenia po ApplicationEvent

@Component
class SmsNotificationListener {
    @EventListener
    void onOrderPlaced(OrderPlacedEvent event) {
        System.out.println("SMS dla zamowienia: " + event.orderId());
    }
}

@Component
class InventoryUpdateListener {
    @EventListener
    void onOrderPlaced(OrderPlacedEvent event) {
        System.out.println("Aktualizuje magazyn dla: " + event.orderId());
    }
}
